var nativeWorkflows = new Map([
  ...workspaceNames.map((name) => [name, workspaceNative]),
  ...libraryNames.map((name) => [name, libraryNative]),
  ...schematicNames.map((name) => [name, schematicNative]),
  ...ruleNames.map((name) => [name, rulesNative]),
  ...boardRouteNames.map((name) => [name, boardRouteNative]),
  ...boardNames.map((name) => [name, boardNative])
]);
var nativeWorkflow = (action, p, dispatch, options) => nativeWorkflows.get(action)(action, p, dispatch, options);

