// ../direct/reference.mjs
function referenceInventory() {
  return { version: catalog_default.version, topicCount: catalog_default.topics.length, ruleCount: catalog_default.topics.reduce((n2, t) => n2 + t.rules.length, 0), sourceCount: catalog_default.sources.length, exampleProjectCount: examples_default.examples.length, contentSha256: sha256(JSON.stringify([catalog_default, examples_default])) };
}
function selected2(query = "", stage = "") {
  query = query.trim().toLowerCase();
  stage = { review: "", requirements: "spec", verification: "verified" }[stage] ?? stage;
  if (stage && stage !== "all" && !catalog_default.topics.some((t) => [t.stage, t.id].includes(stage)))
    bad("Unknown stage/topic. Valid stages: " + [...new Set(catalog_default.topics.map((t) => t.stage))].join(", ") + ". Use reference.search for topic IDs.");
  return catalog_default.topics.filter((t) => !stage || stage === "all" || [t.stage, t.id].includes(stage)).map((t) => {
    const words = [t.id, t.title, ...t.aliases].map((s) => s.toLowerCase()), text = words.join(" ");
    const score = !query ? 1 : words.reduce((n2, s) => n2 + (query.includes(s) ? 10 : 0), 0) + query.split(/\s+/).filter((w) => w.length >= 2 && text.includes(w)).length;
    return { t, score };
  }).filter((x) => x.score).sort((a, b) => b.score - a.score).map((x) => x.t);
}
var sourcesFor = (topics) => catalog_default.sources.filter((s) => topics.some((t) => t.sourceIds.includes(s.id)));
function reference(action, p) {
  if (action === "reference.examples") {
    const matches2 = examples_default.examples.filter((e) => !p.query || `${e.id} ${e.name} ${e.project}`.toLowerCase().includes(p.query.toLowerCase()));
    return ok(action, { count: matches2.length, total: examples_default.examples.length, generatedAt: examples_default.generatedAt, examples: matches2.map((e) => p.includeFiles ? e : { id: e.id, name: e.name, project: e.project, reviewStatus: "indexed-not-electrically-qualified" }), warning: "Local demos inventory, not production approval; hashes are the indexed source snapshot. Verify current files before reuse; never modify original demos." });
  }
  if (action === "reference.get") {
    const topic = catalog_default.topics.find((t) => t.id === p.id);
    if (!topic)
      bad("Unknown reference id; use reference.search");
    return ok(action, { version: catalog_default.version, topic, sources: sourcesFor([topic]) });
  }
  const plan = action === "reference.plan", limit = p.limit ?? (plan ? catalog_default.topics.length : 6);
  if (!Number.isInteger(limit) || limit < 1 || limit > 20)
    bad("limit must be 1..20");
  let topics = selected2(p.query, p.stage), matchKind = "topic-match";
  if (plan && !topics.length && !p.stage) {
    topics = [...selected2("", "spec"), ...selected2("", "verified")];
    matchKind = "baseline-only; refine query or use reference.search to select task-specific cards";
  }
  const count = topics.length;
  topics = topics.slice(0, limit);
  return ok(action, plan ? { version: catalog_default.version, matchKind, policy: catalog_default.policy, authorityOrder: catalog_default.authorityOrder, count, topics, sources: sourcesFor(topics), unknownInputPolicy: "Do independent work first; list unresolved design decisions. Never invent safety/manufacturing/interface constraints or mark unknown evidence passed.", releasePolicy: "Use release.template/snapshot/check; workflow flags are task tracking only. Fabrication evidence and production qualification are separate." } : { version: catalog_default.version, count, topics: topics.map((t) => ({ id: t.id, title: t.title, stage: t.stage, ruleCount: t.rules.length, requiredInputs: t.requiredInputs })), next: "reference.get with a returned id; reference.plan for stage constraints" });
}

// ../direct/audit.mjs
import fs19 from "node:fs";
import path19 from "node:path";
// ../direct/data/audit-rules.json
var audit_rules_default = {
  evidenceRequiredBeyondDrc: [
    "manufacturer process limits and stackup",
    "datasheet-based footprint/pin/electrical review",
    "mechanical/assembly fit",
    "design-specific power, thermal, high-speed and safety constraints where applicable"
  ],
  execution: "backend-only; frontend displays results, never evaluates engineering rules",
  footprintCategories: [
    "pad geometry and drill/copper-layer consistency",
    "courtyard/fabrication/reference definitions",
    "datasheet pin mapping and exposed-pad identity",
    "package dimensions and assembly orientation",
    "3D/mechanical fit"
  ],
  manufacturingProfile: {
    comparison: "project global minima must meet the profile; custom-rule overrides require review too",
    format: "JSON object",
    requiredPositiveMm: [
      "minClearanceMm",
      "minTrackWidthMm",
      "minDrillMm",
      "minAnnularWidthMm",
      "minCopperEdgeClearanceMm"
    ],
    source: "manufacturer process specification; never invented defaults"
  },
  nativeScope: [
    "all enabled native DRC providers",
    "all track errors",
    "all severities including exclusions",
    "zone refill in memory without saving",
    "board/schematic parity",
    "schematic ERC",
    "disabled-check inventory",
    "project rule and custom .kicad_dru provenance"
  ],
  pcbCategories: [
    "shorts and connectivity",
    "clearance and creepage",
    "track widths",
    "via/drill/annulus and hole spacing",
    "copper/board edges and outlines",
    "solder mask and paste",
    "silkscreen",
    "zones and thermal connections",
    "courtyard and footprint geometry",
    "library and schematic parity",
    "length/differential-pair constraints from the project"
  ],
  policy: "Never equate zero DRC with fabrication readiness. Missing reports, ignored checks, unknown limits and unverified datasheet/mechanical assumptions remain explicit blockers. Never relax or disable project rules automatically.",
  sources: [
    "https://docs.kicad.org/master/en/cli/cli.html#pcb_drc",
    "https://docs.kicad.org/master/en/cli/cli.html#schematic_erc",
    "https://klc.kicad.org/footprint/"
  ],
  version: "2026-10-20.2"
};

// ../direct/audit.mjs
function inputFile(file3, extension) {
  if (typeof file3 !== "string" || !file3)
    bad("Input file is required");
  file3 = path19.resolve(file3);
  if (path19.extname(file3).toLowerCase() !== extension || !fs19.statSync(file3).isFile())
    bad(`Expected a regular ${extension} file`);
  return file3;
}
function auditFootprint(p) {
  const input = inputFile(p.input, ".kicad_mod");
  if (fs19.statSync(input).size > 16 * 1024 * 1024)
    bad("Footprint exceeds 16 MiB");
  const root2 = parse9(fs19.readFileSync(input, "utf8"));
  if (!["footprint", "module"].includes(head(root2)))
    bad("Expected a footprint/module expression");
  const findings = [], definitions = { courtyard: false, "fabrication-layer": false, reference: false, value: false };
  let padCount = 0;
  const add2 = (name, status, detail) => findings.push({ name, status, detail });
  const positive2 = (v) => Number.isFinite(Number(v)) && Number(v) > 0;
  function visit(node) {
    const name = head(node), v = values(node);
    if (name === "layer") {
      if (v[0]?.endsWith(".CrtYd"))
        definitions.courtyard = true;
      if (v[0]?.endsWith(".Fab"))
        definitions["fabrication-layer"] = true;
    }
    if (name === "fp_text") {
      if (v[0] === "reference")
        definitions.reference = true;
      if (v[0] === "value")
        definitions.value = true;
    }
    if (name === "property") {
      if (v[0] === "Reference")
        definitions.reference = true;
      if (v[0] === "Value")
        definitions.value = true;
    }
    if (name === "pad") {
      padCount++;
      const [id, kind] = v, size = values(child(node, "size")), layers = values(child(node, "layers"));
      if (!positive2(size[0]) || !positive2(size[1]))
        add2("pad-size", "fail", `Pad ${id} needs positive X/Y dimensions`);
      if (!layers.length)
        add2("pad-layers", "fail", `Pad ${id} has no layers`);
      if (kind !== "np_thru_hole" && (!id || !layers.some((l) => l.endsWith(".Cu"))))
        add2("electrical-pad", "fail", "Electrical pad needs number and copper layer");
      if (["thru_hole", "np_thru_hole"].includes(kind)) {
        const drill = values(child(node, "drill")), dims = drill[0] === "oval" ? drill.slice(1, 3) : [drill[0], drill[0]];
        if (dims.some((d) => !positive2(d)))
          add2("pad-drill", "fail", `Pad ${id} needs positive drill dimensions`);
        else if (kind === "thru_hole" && dims.some((d, i) => Number(d) >= Number(size[i])))
          add2("pad-annulus", "fail", `Pad ${id} drill leaves no annular ring`);
      }
    }
    for (const c of node.children ?? [])
      if (c.children)
        visit(c);
  }
  visit(root2);
  if (!padCount)
    add2("pads", "blocked", "No pads; confirm this is intentionally mechanical");
  for (const [name, present] of Object.entries(definitions))
    if (!present)
      add2(name, "blocked", "Definition missing; review package/library requirements");
  const data = { input, sha256: hashFile(input), padCount, findings, structuralChecksPassed: !findings.length, readyForFabrication: false, pendingEvidence: ["Native board DRC for clearances, courtyard closure and solder mask", "Datasheet pin mapping, package dimensions, exposed pad and polarity", "3D/mechanical/assembly fit; structural checks are not complete KLC or IPC-7351 certification"] };
  return findings.length ? fail("audit.footprint", "FOOTPRINT_NOT_PASSED", "Invalid geometry or incomplete definitions", data) : ok("audit.footprint", data);
}
function nativeCheck(name, result) {
  const report = result?.data?.reportJson, blocked2 = (detail) => ({ name, status: "blocked", detail });
  if (!result?.ok || !report)
    return blocked2(result ?? "Missing native result");
  const arrays = ["violations", ...name === "native-drc" ? ["unconnected_items", "schematic_parity"] : [], "ignored_checks", "included_severities"];
  for (const key of arrays)
    if (!Array.isArray(report[key]))
      return blocked2("Native array missing or malformed: " + key);
  for (const s of ["error", "warning", "exclusion"])
    if (!report.included_severities.includes(s))
      return blocked2("Full severity scope missing: " + s);
  const violations = ["violations", "unconnected_items", "schematic_parity"].reduce((n2, k) => n2 + (report[k]?.length ?? 0), 0);
  return { name, status: violations || result.data.status === "violations" ? "fail" : result.data.status === "clean" && !report.ignored_checks.length ? "pass" : "blocked", detail: { violations, ignoredChecks: report.ignored_checks, report: result.data.report, nativeReport: report } };
}
async function audit(p, dispatch) {
  const board = inputFile(required3(p, "board"), ".kicad_pcb"), stem = board.slice(0, -".kicad_pcb".length), dir = tempDir("kicad-design-audit-");
  const report = { policyVersion: audit_rules_default.version, createdAt: new Date().toISOString(), board, inputSha256: {}, checks: [], pendingEvidence: [], nativeChecksPassed: false, readyForFabrication: false, note: "Native checks audit the saved snapshot using project rules. Datasheet, manufacturing, mechanical and application-specific evidence is required separately. No source design is changed." };
  const add2 = (name, status, detail) => report.checks.push({ name, status, ...detail !== undefined ? { detail } : {} });
  const capture = (file3) => {
    report.inputSha256[file3] = hashFile(file3);
  };
  capture(board);
  for (const f of [stem + ".kicad_pro", stem + ".kicad_dru"])
    if (fs19.existsSync(f))
      capture(f);
  let constraints = {};
  try {
    constraints = readJSON(stem + ".kicad_pro").board?.design_settings?.rules ?? {};
  } catch {}
  add2("project-rules", Object.keys(constraints).length ? "pass" : "blocked", constraints);
  let schematic = p.schematic || (fs19.existsSync(stem + ".kicad_sch") ? stem + ".kicad_sch" : "");
  if (schematic) {
    schematic = inputFile(schematic, ".kicad_sch");
    capture(schematic);
  }
  const artifacts = [];
  for (const [name, action, payload] of [
    ["native-drc", "board.drc.run", { input: board, allTrackErrors: true, refillZones: true, schematicParity: Boolean(schematic) }],
    ...schematic ? [["native-erc", "schematic.erc.run", { input: schematic }]] : []
  ]) {
    const result = await dispatch(action, { ...payload, severityAll: true, full: true, format: "json", output: path19.join(dir, name + ".json") });
    artifacts.push(...result.artifacts ?? []);
    report.checks.push(nativeCheck(name, result));
  }
  if (!schematic)
    add2("native-erc-and-parity", "blocked", "Corresponding schematic is missing");
  else if (schematic !== stem + ".kicad_sch")
    add2("schematic-parity", "blocked", "Explicit schematic is not the board sibling");
  const profile = p.manufacturingProfile || (fs19.existsSync(path19.join(path19.dirname(board), "manufacturing.json")) ? path19.join(path19.dirname(board), "manufacturing.json") : "");
  if (!profile)
    add2("manufacturing-constraints", "blocked", "Manufacturer limits and stackup have not been supplied");
  else {
    const file3 = path19.resolve(profile), limits = readJSON(file3);
    capture(file3);
    const pairs2 = { minClearanceMm: "min_clearance", minTrackWidthMm: "min_track_width", minDrillMm: "min_through_hole_diameter", minAnnularWidthMm: "min_via_annular_width", minCopperEdgeClearanceMm: "min_copper_edge_clearance" };
    const details = Object.entries(pairs2).map(([name, key]) => ({ name, status: !Number.isFinite(limits[name]) || limits[name] <= 0 || !Number.isFinite(constraints[key]) ? "blocked" : constraints[key] < limits[name] ? "fail" : "pass", detail: { manufacturerMinMm: limits[name], projectMinMm: constraints[key] } }));
    add2("manufacturing-constraints", details.some((d) => d.status === "fail") ? "fail" : details.some((d) => d.status === "blocked") ? "blocked" : "pass", details);
    if (fs19.existsSync(stem + ".kicad_dru"))
      report.pendingEvidence.push("Review custom-rule overrides against manufacturer limits; global minima cannot prove every constraint.");
  }
  for (const [file3, before] of Object.entries(report.inputSha256)) {
    try {
      if (hashFile(file3) !== before)
        add2("snapshot-stability", "blocked", file3);
    } catch {
      add2("snapshot-stability", "blocked", file3);
    }
  }
  report.nativeChecksPassed = Boolean(schematic) && report.checks.every((c) => !c.name.startsWith("native-") && !["snapshot-stability", "schematic-parity"].includes(c.name) || c.status === "pass");
  for (const c of report.checks)
    if (c.status !== "pass")
      report.pendingEvidence.push(`${c.name}: ${c.status}`);
  report.pendingEvidence.push("Datasheet-based footprint/pin/electrical review and package identity remain unverified.", "Mechanical/assembly fit and application-specific electrical, thermal, high-speed and safety constraints require separate evidence.");
  const output = path19.resolve(p.output ?? path19.join(dir, "audit.json"));
  writeJSON(output, report, { exclusive: true });
  artifacts.push(output);
  return report.checks.every((c) => c.status === "pass") ? ok("audit.run", report, artifacts) : fail("audit.run", "AUDIT_NOT_PASSED", "Violations or incomplete evidence; see checks and artifacts", report, artifacts);
}

// ../direct/release.mjs
